const incoming = $input.first().json || {};
const body = incoming.body && typeof incoming.body === "object" && !Array.isArray(incoming.body) ? incoming.body : incoming;
const WORKFLOW_NAME = "MOEX_ROUTE_B_GITHUB_EXECUTION_REQUEST_INTAKE_V1_10_3";
const SPEC_VERSION = "1.10.3";
const EXPECTED_REPOSITORY = "Viktoryyyyy/moex-robot";
const DEFAULT_REGISTRY_PATH = "docs/sot/context/registry.route_b.v1.yaml";
const errors = [];

const isPlainObject = (value) => value !== null && typeof value === "object" && !Array.isArray(value);
const asString = (value) => value === undefined || value === null ? "" : String(value).trim();
const addError = (code, field, message) => errors.push({ code, field, message });

function normalizeStringArray(value) {
  if (Array.isArray(value)) {
    return value.map((entry) => asString(entry)).filter(Boolean);
  }
  if (typeof value === "string" && value.trim()) {
    return value.split(",").map((entry) => entry.trim()).filter(Boolean);
  }
  return [];
}

function validateRepoPath(path, field) {
  const value = asString(path);
  if (!value) {
    addError("missing_path", field, field + " is required");
    return null;
  }
  if (value.startsWith("/") || value.startsWith("~") || value.includes("\\") || value.split("/").includes("..")) {
    addError("unsafe_repo_path", field, "repo path must be relative and must not contain absolute/home/backslash/dotdot markers");
  }
  const normalized = value.toLowerCase();
  const forbidden = ["src/moex_runtime/", "moex_runtime/", "live_adapter.py", "/live/", "broker", "trading", "runtime/live"];
  if (forbidden.some((token) => normalized.includes(token))) {
    addError("runtime_live_trading_broker_scope_forbidden", field, "runtime/live/broker/trading scope is forbidden");
  }
  return value;
}

function validateRoleRef(value, defaultRoleId, defaultRefKey, defaultRefValue) {
  if (isPlainObject(value) && isPlainObject(value.role_context_ref)) {
    return value;
  }
  const result = {
    role_context_ref: {
      role_id: defaultRoleId,
      role_context_version: "v1"
    }
  };
  result[defaultRefKey] = defaultRefValue;
  return result;
}

if (body.schema_version !== "route_b_github_execution_request_intake.v1") {
  addError("invalid_schema_version", "schema_version", "schema_version must be route_b_github_execution_request_intake.v1");
}

const workflowRunId = asString(body.workflow_run_id);
const requestId = asString(body.request_id);
const repositoryFullName = asString(body.repository_full_name || EXPECTED_REPOSITORY);
const baseBranch = asString(body.base_branch || "main");
const baseSha = asString(body.base_sha);
const featureBranch = asString(body.feature_branch || body.branch_name);

if (!workflowRunId) addError("missing_workflow_run_id", "workflow_run_id", "workflow_run_id is required");
if (!requestId) addError("missing_request_id", "request_id", "request_id is required");
if (repositoryFullName !== EXPECTED_REPOSITORY) addError("invalid_repository_full_name", "repository_full_name", "repository_full_name must be " + EXPECTED_REPOSITORY);
if (baseBranch !== "main") addError("base_branch_not_main", "base_branch", "base_branch must be main");
if (!/^[0-9a-f]{40}$/i.test(baseSha)) addError("invalid_base_sha", "base_sha", "base_sha must be a 40-character commit SHA");
if (!featureBranch) addError("missing_feature_branch", "feature_branch", "feature_branch is required");
if (featureBranch && !featureBranch.startsWith("n8n/")) addError("branch_prefix_not_n8n", "feature_branch", "feature_branch must start with n8n/");
if (featureBranch && (featureBranch.includes("..") || featureBranch.includes(" "))) addError("unsafe_feature_branch", "feature_branch", "feature_branch must not contain spaces or dotdot");

const approvedFileScope = normalizeStringArray(body.approved_file_scope || body.allowed_paths);
if (approvedFileScope.length === 0) {
  addError("missing_approved_file_scope", "approved_file_scope", "approved_file_scope must be a non-empty array");
}
const approvedPaths = approvedFileScope.map((path, index) => validateRepoPath(path, "approved_file_scope[" + index + "]")).filter(Boolean);

let filePayload = body.approved_file_changes_payload;
if (!isPlainObject(filePayload)) {
  filePayload = { files: Array.isArray(body.file_changes) ? body.file_changes : [] };
}
const files = Array.isArray(filePayload.files) ? filePayload.files : [];
if (files.length === 0) {
  addError("missing_approved_file_changes_payload", "approved_file_changes_payload.files", "approved_file_changes_payload.files must be a non-empty array");
}

const normalizedFiles = [];
const approvedSet = new Set(approvedPaths);
for (let index = 0; index < files.length; index++) {
  const raw = files[index];
  if (!isPlainObject(raw)) {
    addError("invalid_file_change", "approved_file_changes_payload.files[" + index + "]", "file change must be an object");
    continue;
  }
  const path = validateRepoPath(raw.path, "approved_file_changes_payload.files[" + index + "].path");
  const operation = asString(raw.operation || raw.status || "update").toLowerCase();
  if (["delete", "deleted", "remove", "removed"].includes(operation)) {
    addError("deleted_file_operation_forbidden", "approved_file_changes_payload.files[" + index + "].operation", "delete/remove operations are forbidden");
  }
  if (!["add", "added", "create", "created", "modify", "modified", "update", "updated", "upsert"].includes(operation)) {
    addError("unsupported_file_change_operation", "approved_file_changes_payload.files[" + index + "].operation", "unsupported file operation");
  }
  if (path && !approvedSet.has(path)) {
    addError("changed_file_outside_approved_scope", "approved_file_changes_payload.files[" + index + "].path", "file change path is outside approved_file_scope");
  }
  const hasContent = typeof raw.content === "string";
  const hasBase64 = typeof raw.content_base64 === "string" && raw.content_base64.length > 0;
  if (!hasContent && !hasBase64) {
    addError("missing_file_content", "approved_file_changes_payload.files[" + index + "]", "file change must include content or content_base64");
  }
  normalizedFiles.push({
    path,
    operation,
    content: hasBase64 ? raw.content_base64 : raw.content,
    encoding: hasBase64 ? "base64" : "utf-8"
  });
}

const changedPaths = normalizedFiles.map((file) => file.path).filter(Boolean);
const exactScopeRequired = body.file_scope_exact !== false;
if (exactScopeRequired) {
  const a = Array.from(new Set(changedPaths)).sort();
  const b = Array.from(new Set(approvedPaths)).sort();
  if (JSON.stringify(a) !== JSON.stringify(b)) {
    addError("changed_files_do_not_match_exact_approved_scope", "approved_file_changes_payload.files", "changed files must exactly match approved_file_scope");
  }
}

const pmL2RequestRef = validateRoleRef(body.pm_l2_request_ref, "PM_L2_PHASE_OWNER", "request_ref", requestId);
const pmL3PackageRef = validateRoleRef(body.pm_l3_package_ref, "PM_L3_DELIVERY_VALIDATION_OWNER", "package_ref", workflowRunId);
const pmL3Package = isPlainObject(body.pm_l3_package) ? body.pm_l3_package : (isPlainObject(body.draft_pm_l3_package) ? body.draft_pm_l3_package : null);

const authorityBoundary = {
  merge_authority: "PM_L2_ONLY",
  pm_l2_review_required: true,
  n8n_merge_allowed: false,
  direct_main_write_allowed: false,
  force_push_allowed: false,
  file_delete_allowed: false,
  executor_merge_allowed: false,
  ci_passed_is_not_merge_approval: true
};

const routeBGitHubExecutionRequest = {
  schema_version: "route_b_github_execution_request.v1",
  workflow_run_id: workflowRunId,
  request_id: requestId,
  repository_full_name: repositoryFullName,
  base_branch: baseBranch,
  base_sha: baseSha,
  approved_file_scope: approvedPaths,
  route_b_context_registry_ref: {
    path: DEFAULT_REGISTRY_PATH,
    source_of_truth: "github_repo",
    ref: baseSha
    },
  pm_l2_request_ref: pmL2RequestRef,
  pm_l3_package_ref: pmL3PackageRef,
  execution_scope: {
    allowed_paths: approvedPaths,
    approved_file_scope: approvedPaths,
    approved_file_changes_payload: { files: normalizedFiles },
    file_scope_exact: exactScopeRequired,
    delete_files_allowed: false
  },
  branch_plan: {
    source: "base_sha",
    branch_name: featureBranch
  },
  pr_plan: {
    base_branch: baseBranch,
    head_branch: featureBranch,
    draft: false
  },
  validation_requirements: {
    github_actions_workflow: "tests",
    file_scope_exact: exactScopeRequired
  },
  governance_flags: {
    direct_main_write_allowed: false,
    n8n_merge_allowed: false,
    force_push_allowed: false,
    file_delete_allowed: false,
    production_runtime_allowed: false
  },
  rejection_rules: {
    reject_dynamic_marker_tokens: true,
    reject_target_role_context_ref: true,
    reject_missing_role_context_ref: true,
    reject_non_n8n_branch_prefix: true,
    reject_direct_main_write: true,
    reject_n8n_merge: true,
    reject_force_push: true,
    reject_file_delete: true,
    reject_runtime_or_broker_scope: true
  }
};

const approvedFileChangesPayload = { files: normalizedFiles };

const eventPayload = {
  schema_version: "route_b_github_execution_request_intake_event.v1",
  workflow_name: WORKFLOW_NAME,
  spec_version: SPEC_VERSION,
  received_at: new Date().toISOString(),
  workflow_run_id: workflowRunId,
  request_id: requestId,
  repository_full_name: repositoryFullName,
  route_b_github_execution_request: routeBGitHubExecutionRequest,
  approved_file_changes_payload: approvedFileChangesPayload,
  pm_l3_package: pmL3Package,
  authority_boundary: authorityBoundary
};

const normalized = {
  workflow_name: WORKFLOW_NAME,
  spec_version: SPEC_VERSION,
  received_at: new Date().toISOString(),
  schema_version: body.schema_version,
  workflow_run_id: workflowRunId,
  request_id: requestId,
  repository_full_name: repositoryFullName,
  base_branch: baseBranch,
  base_sha: baseSha,
  feature_branch: featureBranch,
  approved_file_scope: approvedPaths,
  github_request_valid: errors.length === 0,
  errors,
  event_payload_json: eventPayload,
  authority_boundary: authorityBoundary,
  raw_request_body: body
};

const wrapper = { b64: Buffer.from(JSON.stringify(normalized), "utf8").toString("base64") };

return [{
  json: {
    ...normalized,
    pg_parameter_string: JSON.stringify(wrapper),
    route: "preflight"
  }
}];

const row = $input.first().json || {};
if (row.error) {
  const response = {
    workflow_name: "MOEX_ROUTE_B_GITHUB_EXECUTION_REQUEST_INTAKE_V1_10_3",
    spec_version: "1.10.3",
    http_status_code: 400,
    accepted: false,
    github_request_valid: false,
    workflow_run_id: null,
    request_id: null,
    repository_full_name: null,
    status: "postgres_preflight_error",
    current_state: null,
    current_phase: null,
    event_type: null,
    event_ref: null,
    authority_boundary: {},
    errors: [{ code: "postgres_preflight_error", field: "postgres", message: String(row.error.message || row.error) }]
  };
  return [{ json: { route: "respond_error", http_status_code: 400, response } }];
}

function parseMaybeJson(value, fallback) {
  if (value === undefined || value === null) return fallback;
  if (typeof value === "object") return value;
  if (typeof value === "string") {
    try { return JSON.parse(value); } catch (error) { return fallback; }
  }
  return fallback;
}

const response = parseMaybeJson(row.response, {});
const shouldPersist = row.should_persist === true || row.should_persist === "true";
return [{
  json: {
    ...row,
    response,
    http_status_code: Number(row.http_status_code || response.http_status_code || 400),
    route: shouldPersist ? "persist" : "respond_error"
  }
}];

const row = $input.first().json || {};
const baseResponse = {
  workflow_name: "MOEX_ROUTE_B_GITHUB_EXECUTION_REQUEST_INTAKE_V1_10_3",
  spec_version: "1.10.3",
  http_status_code: 400,
  accepted: false,
  github_request_valid: false,
  workflow_run_id: null,
  request_id: null,
  repository_full_name: null,
  status: "postgres_persistence_error",
  current_state: null,
  current_phase: null,
  event_type: null,
  event_ref: null,
  authority_boundary: {},
  errors: []
};

if (row.error) {
  baseResponse.errors = [{ code: "postgres_persistence_error", field: "postgres", message: String(row.error.message || row.error) }];
  return [{ json: { http_status_code: 400, response: baseResponse } }];
}

function parseMaybeJson(value, fallback) {
  if (value === undefined || value === null) return fallback;
  if (typeof value === "object") return value;
  if (typeof value === "string") {
    try { return JSON.parse(value); } catch (error) { return fallback; }
  }
  return fallback;
}

const response = parseMaybeJson(row.response, baseResponse);
return [{ json: { http_status_code: Number(response.http_status_code || row.http_status_code || 202), response } }];
